import{_ as i,o as t,c as n,a3 as r}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Einstellungs-Bildschirm ergänzen","description":"Eigene Einträge wie Datenschutz oder Impressum über das Grid „settings\\" hinzufügen.","frontmatter":{"title":"Einstellungs-Bildschirm ergänzen","description":"Eigene Einträge wie Datenschutz oder Impressum über das Grid „settings\\" hinzufügen."},"headers":[],"relativePath":"apptiveteams/einstellungen.md","filePath":"apptiveteams/einstellungen.md","lastUpdated":1786357627000}'),d={name:"apptiveteams/einstellungen.md"};function s(a,e,l,c,h,o){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="einstellungs-bildschirm-erganzen" tabindex="-1">Einstellungs-Bildschirm ergänzen <a class="header-anchor" href="#einstellungs-bildschirm-erganzen" aria-label="Permalink to &quot;Einstellungs-Bildschirm ergänzen&quot;">​</a></h1><p>Über das Grid mit dem Key <code>settings</code> fügen Sie dem Einstellungs-Bildschirm der App eigene Einträge hinzu — etwa Links zu Datenschutz, Impressum oder Ihrem Hilfebereich. Jede Zeile wird zu einem Eintrag, der beim Antippen die hinterlegte Adresse öffnet.</p><h2 id="die-felder" tabindex="-1">Die Felder <a class="header-anchor" href="#die-felder" aria-label="Permalink to &quot;Die Felder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>title</code></td><td>Text</td><td>ja</td><td>Beschriftung des Eintrags</td></tr><tr><td><code>url</code></td><td>Weblink</td><td>ja</td><td>Adresse, die beim Antippen geöffnet wird</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Der Feld-Key heißt hier <code>url</code>, nicht <code>uri</code></p><p>In den Grids <code>tabs</code> und <code>TilesGrid</code> heißt das Adressfeld <code>uri</code>. Im <code>settings</code>-Grid heißt es <code>url</code>. Wer die Felder aus einem anderen Grid kopiert, übernimmt leicht den falschen Key — und der Eintrag erscheint dann nicht.</p></div><h2 id="was-immer-vorhanden-ist" tabindex="-1">Was immer vorhanden ist <a class="header-anchor" href="#was-immer-vorhanden-ist" aria-label="Permalink to &quot;Was immer vorhanden ist&quot;">​</a></h2><p>Unabhängig von Ihrer Konfiguration enthält der Einstellungs-Bildschirm immer:</p><ul><li>das Profil der angemeldeten Person</li><li><strong>Abmelden</strong></li><li><strong>Team wechseln</strong></li><li>die App-Version</li><li>die Möglichkeit, das eigene Konto zu löschen</li></ul><div class="tip custom-block"><p class="custom-block-title">Der übliche Platz für Pflichtangaben</p><p>Datenschutzerklärung und Impressum sind für eine App, die Sie an Ihre Belegschaft ausgeben, in der Regel erforderlich. Der Einstellungs-Bildschirm ist der Ort, an dem Nutzende sie erwarten — und die App-Stores prüfen darauf.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptiveteams/team-space">Team Space einrichten</a></li><li><a href="/apptiveteams/tabs">Tabs einrichten</a></li><li><a href="/apptiveteams/fehlerbehebung">Tipps und Fehlerbehebung</a></li></ul>',11)])])}const p=i(d,[["render",s]]);export{m as __pageData,p as default};
